"""Record explicit visual inspection of FITRR use cases, activities and legend."""
import argparse,hashlib,json,re
from pathlib import Path
import kb

def main(root,newly_inspected=()):
    manifest=json.loads((root/'work/fitrr-activities.json').read_text(encoding='utf-8'));renders={x['diagram']:x for x in json.loads((root/'work/fitrr-activities-render.json').read_text(encoding='utf-8'))};report=root/'tracking/reviews/fitrr-activities.json';prior={x['figure_id']:x for x in json.loads(report.read_text(encoding='utf-8'))['records']} if report.exists() else {};inventory_path=root/'work/documents/src-000320/media-review-inventory.json';inv=json.loads(inventory_path.read_text(encoding='utf-8'));records=[]
    for item in manifest['outputs']:
        fid=item['figure_id'];num=int(fid[4:]);rr=renders[fid];page=root/item['path'];assert rr['result']=='pass';hashes={'mermaid_sha256':hashlib.sha256(page.with_suffix('.mmd').read_bytes()).hexdigest(),'original_sha256':hashlib.sha256((root/item['original']).read_bytes()).hexdigest(),'rendered_png_sha256':hashlib.sha256((root/rr['png']).read_bytes()).hexdigest()}
        assert hashes['mermaid_sha256']==item['mermaid_sha256'] and hashes['original_sha256']==item['original_sha256']
        if fid in prior and num not in newly_inspected:assert all(prior[fid][k]==v for k,v in hashes.items()),'New visual comparison required'
        status='needs-review' if num in (1,11,14) else 'reviewed';issues={1:['issue-000035'],11:['issue-000036'],14:['issue-000032']}.get(num,[])
        rec={**item,**hashes,'date':'2026-11-09','timezone':'Europe/Warsaw','render_result':'pass','renderer':rr['renderer'],'renderer_version':rr['version'],'svg':rr['svg'],'png':rr['png'],'visual_review':'pass','review_status':status,'issue_ids':issues,'checks':['Original source preview and final reconstruction directly viewed.','Actor/use-case labels and each association endpoint checked, including both Equity/Non-Equity branches for each submission.','Repeated Competent Authority actor instances retained.','Every activity node, lane assignment, connector direction, guard, corrective loop and final outcome compared.','All source bars preserved with their incident edges; T22 defines bars as parallel initiation.','Two starts in non-working-day reporting and the empty Reporting Entity lanes in distribution/results retained in text.','Source responsibility and role-notation conflicts remain open; no institutional equivalence inferred.'],'scope':'Visible artwork semantics; layout changes are allowed and source artwork remains available. Native hidden pages/layers and full Word-page review are separate.'};records.append(rec)
        m,b=kb.metadata(page);m.update(review_status=status,render_status='pass',visual_review='pass',visual_review_date='2026-11-09',renderer='Mermaid '+rr['version'],rendered_svg=rr['svg'],rendered_png=rr['png'],issue_ids=issues)
        b=re.sub(r'## Rendering and visual review\n.*','## Rendering and visual review\n\nMermaid '+rr['version']+' with '+rr['renderer']+' parsed and rendered this diagram. On 2026-11-09 (Europe/Warsaw), the original and final reconstruction were directly compared for labels, actors, lane responsibility, all endpoints/directions, guards, parallel bars and corrective loops. Result: **visible-source fidelity pass**. Source conflicts remain open where listed.\n\n'+kb.link(page,root/rr['svg'],'Rendered SVG')+' · '+kb.link(page,root/rr['png'],'Rendered PNG')+' · '+kb.link(page,report,'Hash-bound review evidence')+'\n',b,flags=re.S)
        if num>=8:b+='\nSource notation: '+kb.link(page,root/'domains/securities/reference/message-sets/fitrr/2025/documents/src-000320/tables/tbl-0022.md','T22 legend')+' defines a bar as initiating several actions in parallel. The reconstruction retains these nodes; empty source swimlanes may render as labels rather than a full-height box.\n'
        kb.put(page,kb.front(m)+b)
        for media in inv['media']:
            for occurrence in media['occurrences']:
                if occurrence['figure_id']==fid:
                    occurrence['canonical_diagram']=item['path'];media.update(disposition='source-reconstruction',canonical_diagram=item['path'],visual_review='pass',review_status=status,complete_composite_review='source-preview-compared; full-Word-page-context-separate');ep=root/occurrence['evidence_page'];em,eb=kb.metadata(ep);em.update(review_status=status,disposition='source-reconstruction',canonical_diagram=item['path'],render_status='pass',visual_review='pass');kb.put(ep,kb.front(em)+eb.strip()+'\n')
    legends=[]
    for media in inv['media']:
        for occurrence in media['occurrences']:
            num=int(occurrence['figure_id'][4:])
            if num not in (4,5,6,7):continue
            label={4:'Start Point',5:'End Point',6:'Lozenge (or diamond)',7:'Bar'}[num];media.update(disposition='retained-notation-legend',review_status='reviewed',visual_review='pass',complete_composite_review='T22 four symbol cells compared');ep=root/occurrence['evidence_page'];em,eb=kb.metadata(ep);em.update(review_status='reviewed',disposition='retained-notation-legend',visual_review='pass',limitations=['This is a substantive notation key in T22, not a decorative exclusion or a standalone business diagram.']);eb=re.sub(r'\n<!-- FITRR-LEGEND -->.*','',eb,flags=re.S);kb.put(ep,kb.front(em)+eb.strip()+'\n\n<!-- FITRR-LEGEND -->\nThis symbol is retained as **'+label+'** in T22. Its original PNG was directly viewed on 2026-11-09. It is a notation legend, not a decorative exclusion.\n');legends.append({'figure_id':occurrence['figure_id'],'label':label,'original':media['original'],'original_sha256':media['original_sha256'],'date':'2026-11-09','disposition':'retained-notation-legend','visual_review':'pass'})
    kb.dump(inventory_path,inv);kb.dump(report,{'source_id':manifest['source_id'],'source_sha256':manifest['source_sha256'],'date':'2026-11-09','records':records,'legend_records':legends,'render_pass':len(records),'direct_visual_comparisons':len(records),'reviewed':sum(r['review_status']=='reviewed' for r in records),'needs_review':sum(r['review_status']=='needs-review' for r in records)});print(json.dumps({'diagrams':len(records),'legends':len(legends),'reviewed':sum(r['review_status']=='reviewed' for r in records)}))
if __name__=='__main__':
    p=argparse.ArgumentParser();p.add_argument('--root',type=Path,default=Path(__file__).resolve().parents[1]);p.add_argument('--newly-inspected',type=int,nargs='*',default=[]);a=p.parse_args();main(a.root.resolve(),a.newly_inspected)
